// ---------------------------------------------------------------------------
// The C++ half of the field-function dialect (ADR-001).
//
// Field function sources in this directory are written in a restricted C-like
// dialect that compiles UNMODIFIED as C++ and as HLSL. HLSL already has these
// types and builtins, so everything here is C++-only and this file is empty
// from HLSL's point of view. WGSL is generated by tools/wgslgen and never
// includes this header -- it has its own builtins.
//
// Keep this header small. Every function added here is one more thing the
// generator has to know how to translate.
// ---------------------------------------------------------------------------
#ifndef WORLDGEN_FIELD_TYPES_H
#define WORLDGEN_FIELD_TYPES_H

#ifdef __cplusplus

#include <algorithm>
#include <cmath>
#include <cstdint>
#include <cstring>

typedef uint32_t uint;

struct float2 {
    float x, y;
    float2() : x(0.0f), y(0.0f) {}
    float2(float a, float b) : x(a), y(b) {}
};

struct float3 {
    float x, y, z;
    float3() : x(0.0f), y(0.0f), z(0.0f) {}
    float3(float a, float b, float c) : x(a), y(b), z(c) {}
};

// Bit reinterpretations. Spelled as HLSL spells them; the generator maps these
// to WGSL's bitcast<>. Not a value conversion -- int(-1) and asuint(-1) differ,
// and the noise hash depends on the bit pattern.
inline uint asuint(int v) { uint u; std::memcpy(&u, &v, sizeof(u)); return u; }
inline int  asint(uint v) { int  i; std::memcpy(&i, &v, sizeof(i)); return i; }
inline uint asuint(uint v) { return v; }
inline int  asint(int v) { return v; }

// Brought in rather than redefined: the standard library already declares
// float overloads of these in the global namespace, and a second definition
// is a hard error. HLSL has them as builtins, so the dialect just calls them.
using std::floor;
using std::sqrt;
using std::clamp;
using std::abs;    // the float overload; HLSL and WGSL have it as a builtin
using std::pow;

#endif  // __cplusplus
#endif  // WORLDGEN_FIELD_TYPES_H
